package main
use fmt;
use serde as wire;
use serde::json as json;
#[derive(wire::Serialize,wire::Deserialize)]
type Item struct { Value int }
func main(){wire:=7;_=wire;original:=Item{Value:42};data,err:=json::Marshal(&original,SerializeItem);if err!=nil{panic(err)};copy,err:=json::Unmarshal(data,DeserializeItem);if err!=nil{panic(err)};fmt::Println(string(data),copy.Value)}

