func main(){output:="";match item(){Option::Some(n)=>{output=render(n)},Option::None=>{output="empty"},};{render:=func(int)string{return "local"};match item(){Option::Some(n)=>{output+=" "+render(n)},Option::None=>{output="empty"},}};fmt::Println(output)}

package main
use fmt;
type T struct{}
func(T)M()int{return 9}
func item()Option[int]{return Option::Some(3)}
func Statement()int{result:=0;match item(){Option::Some(n)=>{result=T::M(T{})+n},Option::None=>{},};return result}
func Expression()int{return match item(){Option::Some(n)=>(*T)::M(&T{})+n,Option::None=>0,}}
func main(){v:=T{};fmt::Println(Statement(),Expression(),v.M())}

